// ICSE 10 Mathematics ch20 Trigonometric Identities — practice bank with independent re-solve checks.
// Keys, values and every number in a solution or model answer are typed as literals; each check recomputes them with trig.mjs:
// exact values in Q(sqrt2, sqrt3) at standard angles, exact ratios from one given ratio, and every identity or proof step
// tested at three exact standard angles plus eleven floating-point angles (and shown to fail where it is a false claim).
import { Q, mk, r } from './lib.mjs';
import * as T from './trig.mjs';

const { E, Fl, G, tx, identity, same, only, fails, fromSin, fromCos, fromTan, fromCot, fromSec, fromCosec } = T;
const J = (lines) => lines.join('\n\n');
const d = (s) => `$${s}$`;
const close = (a, b, e = 1e-9) => Math.abs(a - b) < e;
const val = (src, env) => T.num(E(src, env)); // exact value that must be rational, as a JS number
const chain = (...xs) => xs.slice(1).reduce((n, x, i) => n + identity(xs[i], x), 0); // every step equals the previous one
const one = (flags, k) => flags.filter(Boolean).length === 1 && flags[k]; // exactly one true, at index k
const FL = [7, 18, 23, 31, 37, 44, 52, 58, 66, 73, 81];

// =============================================================== MCQ (20)
Q('m01', mk.mcq({ stem: r`Dividing both sides of $\sin^2 A + \cos^2 A = 1$ by $\sin^2 A$ (with $A$ acute) gives which identity?`, opts: [r`$1 + \cot^2 A = \operatorname{cosec}^2 A$`, r`$1 + \tan^2 A = \sec^2 A$`, r`$\tan^2 A + \cot^2 A = 1$`, r`$\cos^2 A + \sec^2 A = 1$`], key: 'a', sol: r`Dividing every term by $\sin^2 A$ gives $1 + \dfrac{\cos^2 A}{\sin^2 A} = \dfrac{1}{\sin^2 A}$, that is $1 + \cot^2 A = \operatorname{cosec}^2 A$. Option (b) is what dividing by $\cos^2 A$ gives.`, d: 1, c: 'recall', t: [1], time: 40 }), (C) => { C.assert(identity('(sin(A)^2+cos(A)^2)/sin(A)^2', '1+cot(A)^2') > 10 && identity('1+cot(A)^2', 'cosec(A)^2') > 10 && identity('(sin(A)^2+cos(A)^2)/cos(A)^2', '1+tan(A)^2') > 10, 'division by sin^2 and by cos^2'); C.assert(fails('tan(A)^2+cot(A)^2', '1') && fails('cos(A)^2+sec(A)^2', '1'), '(c) and (d) are false'); C.key('a'); });

Q('m02', mk.mcq({ stem: r`For every acute angle $\theta$, the product $(1 - \cos^2\theta)\operatorname{cosec}^2\theta$ equals`, opts: ['$1$', r`$\sin^2\theta$`, r`$\cot^2\theta$`, r`$\sec^2\theta$`], key: 'a', sol: r`Since $1 - \cos^2\theta = \sin^2\theta$, the product is $\sin^2\theta \times \dfrac{1}{\sin^2\theta} = 1$. Option (b) forgets to multiply by $\operatorname{cosec}^2\theta$.`, d: 1, c: 'understanding', t: [1], time: 45 }), (C) => { C.assert(one(only('(1-cos(A)^2)*cosec(A)^2', ['1', 'sin(A)^2', 'cot(A)^2', 'sec(A)^2']), 0), 'only (a) is equal'); C.key('a'); });

const r03 = fromSin(9, 41);
Q('m03', mk.mcq({ stem: r`In a right-angled triangle, the acute angle $A$ satisfies $\sin A = \dfrac{9}{41}$. What is $\sec A$?`, opts: [r`$\dfrac{41}{40}$`, r`$\dfrac{41}{9}$`, r`$\dfrac{40}{9}$`, r`$\dfrac{9}{40}$`], key: 'a', sol: r`$\cos^2 A = 1 - \sin^2 A = 1 - \dfrac{81}{1681} = \dfrac{1600}{1681}$, so $\cos A = \dfrac{40}{41}$ and $\sec A = \dfrac{41}{40}$. Option (b) is $\operatorname{cosec} A$, (c) is $\cot A$ and (d) is $\tan A$.`, d: 2, c: 'understanding', t: [1], time: 75 }), (C) => { C.which([r`$\dfrac{41}{40}$`, r`$\dfrac{41}{9}$`, r`$\dfrac{40}{9}$`, r`$\dfrac{9}{40}$`], d(tx(G('sec(T)', r03)))); C.assert(tx(G('cosec(T)', r03)) === r`\dfrac{41}{9}` && tx(G('cot(T)', r03)) === r`\dfrac{40}{9}` && tx(G('tan(T)', r03)) === r`\dfrac{9}{40}` && 1681 - 81 === 1600, 'distractors are the other ratios'); });

const r04 = fromTan(20, 21);
Q('m04', mk.mcq({ stem: r`An acute angle $\theta$ has $\tan\theta = \dfrac{20}{21}$. The value of $\cos\theta$ is`, opts: [r`$\dfrac{21}{29}$`, r`$\dfrac{20}{29}$`, r`$\dfrac{21}{41}$`, r`$\dfrac{29}{20}$`], key: 'a', sol: r`$\sec^2\theta = 1 + \tan^2\theta = 1 + \dfrac{400}{441} = \dfrac{841}{441}$, so $\sec\theta = \dfrac{29}{21}$ and $\cos\theta = \dfrac{21}{29}$. Option (c) adds $20 + 21$ instead of using $20^2 + 21^2 = 29^2$.`, d: 2, c: 'understanding', t: [1], time: 75 }), (C) => { C.which([r`$\dfrac{21}{29}$`, r`$\dfrac{20}{29}$`, r`$\dfrac{21}{41}$`, r`$\dfrac{29}{20}$`], d(tx(G('cos(T)', r04)))); C.assert(tx(G('sin(T)', r04)) === r`\dfrac{20}{29}` && tx(G('cosec(T)', r04)) === r`\dfrac{29}{20}` && 400 + 441 === 841, '(b) and (d)'); });

Q('m05', mk.mcq({ stem: r`Which expression is the same as $\sec^2\theta - 1$ for an acute angle $\theta$?`, opts: [r`$\tan^2\theta$`, r`$\sin^2\theta$`, r`$\cot^2\theta$`, r`$\cos^2\theta$`], key: 'a', sol: r`From $1 + \tan^2\theta = \sec^2\theta$ we get $\sec^2\theta - 1 = \tan^2\theta$.`, d: 1, c: 'recall', t: [1], time: 30 }), (C) => { C.assert(one(only('sec(A)^2-1', ['tan(A)^2', 'sin(A)^2', 'cot(A)^2', 'cos(A)^2']), 0), 'only (a)'); C.key('a'); });

Q('m06', mk.mcq({ stem: r`The value of $\sin^2 25^\circ + \sin^2 65^\circ$ is`, opts: ['$1$', '$0$', r`$\dfrac{1}{2}$`, '$2$'], key: 'a', sol: r`$65^\circ = 90^\circ - 25^\circ$, so $\sin 65^\circ = \cos 25^\circ$. The sum becomes $\sin^2 25^\circ + \cos^2 25^\circ = 1$.`, d: 2, c: 'understanding', t: [3], time: 60 }), (C) => { C.assert(close(Fl('sin(A)^2+sin(65)^2', { A: 25 }), 1) && identity('sin(A)^2+sin(90-A)^2', '1') > 10, 'equals 1'); C.key('a'); });

Q('m07', mk.mcq({ stem: r`Using complementary angles, find $\dfrac{\cos 54^\circ}{\sin 36^\circ} + \tan 22^\circ\tan 68^\circ$.`, opts: ['$2$', '$1$', '$0$', r`$\dfrac{1}{2}$`], key: 'a', sol: r`$\cos 54^\circ = \sin 36^\circ$, so the first term is $1$. Also $\tan 68^\circ = \cot 22^\circ$, so $\tan 22^\circ\tan 68^\circ = 1$. The sum is $1 + 1 = 2$.`, d: 2, c: 'application', t: [3], time: 75 }), (C) => { C.assert(close(Fl('cos(54)/sin(36)+tan(22)*tan(68)'), 2), 'equals 2'); C.key('a'); });

Q('m08', mk.mcq({ stem: r`In terms of its complementary angle, $\cot 38^\circ$ is equal to`, opts: [r`$\tan 52^\circ$`, r`$\tan 38^\circ$`, r`$\cot 52^\circ$`, r`$\sec 52^\circ$`], key: 'a', sol: r`$\cot\theta = \tan(90^\circ - \theta)$, so $\cot 38^\circ = \tan 52^\circ$.`, d: 1, c: 'recall', t: [3], time: 30 }), (C) => { const v = Fl('cot(A)', { A: 38 }); C.assert(close(v, Fl('tan(A)', { A: 52 })) && ![38, 52].every((x) => close(v, Fl('tan(A)', { A: x }))) && !close(v, Fl('cot(A)', { A: 52 })) && !close(v, Fl('sec(A)', { A: 52 })), 'only tan 52 equals cot 38'); C.key('a'); });

Q('m09', mk.mcq({ stem: r`In triangle $PQR$ right-angled at $Q$, which of the following equals $\sin P$?`, opts: [r`$\cos R$`, r`$\cos P$`, r`$\sin R$`, r`$\tan R$`], key: 'a', sol: r`The acute angles satisfy $P + R = 90^\circ$, so $R = 90^\circ - P$ and $\sin P = \cos(90^\circ - P) = \cos R$.`, d: 1, c: 'recall', t: [3], time: 40 }), (C) => { C.assert(one(only('sin(A)', ['cos(90-A)', 'cos(A)', 'sin(90-A)', 'tan(90-A)']), 0), 'with R = 90 - P only cos R'); C.key('a'); });

Q('m10', mk.mcq({ stem: r`For an acute angle $\theta$, the fraction $\dfrac{1 + \tan^2\theta}{1 + \cot^2\theta}$ simplifies to`, opts: [r`$\tan^2\theta$`, r`$\cot^2\theta$`, '$1$', r`$\sec^2\theta\operatorname{cosec}^2\theta$`], key: 'a', sol: r`The numerator is $\sec^2\theta$ and the denominator is $\operatorname{cosec}^2\theta$, so the fraction is $\dfrac{\sin^2\theta}{\cos^2\theta} = \tan^2\theta$. Option (b) inverts the fraction.`, d: 2, c: 'understanding', t: [2], time: 75 }), (C) => { C.assert(one(only('(1+tan(A)^2)/(1+cot(A)^2)', ['tan(A)^2', 'cot(A)^2', '1', 'sec(A)^2*cosec(A)^2']), 0), 'only (a)'); C.key('a'); });

Q('m11', mk.mcq({ stem: r`Evaluate $\sec^2 45^\circ - \tan^2 45^\circ + \operatorname{cosec}^2 30^\circ - \cot^2 30^\circ$ using the values of the standard angles.`, opts: ['$2$', '$1$', '$3$', '$0$'], key: 'a', sol: r`$\sec^2 45^\circ = 2$, $\tan^2 45^\circ = 1$, $\operatorname{cosec}^2 30^\circ = 4$ and $\cot^2 30^\circ = 3$, so the value is $2 - 1 + 4 - 3 = 2$.`, d: 2, c: 'understanding', t: [3], time: 75 }), (C) => { C.assert(val('sec(45)^2-tan(45)^2+cosec(30)^2-cot(30)^2') === 2 && val('sec(45)^2') === 2 && val('cosec(30)^2') === 4 && val('cot(30)^2') === 3, 'exact value 2'); C.sol([2, 1, 4, 3]); });

Q('m12', mk.mcq({ stem: r`One of these relations is false for every acute angle $\theta$. Which one?`, opts: [r`$\sin^2\theta + \cos^2\theta = 1$`, r`$1 + \tan^2\theta = \sec^2\theta$`, r`$\sin\theta + \cos\theta = 1$`, r`$1 + \cot^2\theta = \operatorname{cosec}^2\theta$`], key: 'c', sol: r`Options (a), (b) and (d) are the three Pythagorean identities. For an acute angle, $\sin\theta + \cos\theta > 1$: at $\theta = 30^\circ$ the sum is $\dfrac{1}{2} + \dfrac{\sqrt{3}}{2} \ne 1$.`, d: 2, c: 'analysis', t: [1], time: 60 }), (C) => { C.assert(FL.every((a) => Math.abs(Fl('sin(A)+cos(A)', { A: a }) - 1) > 1e-3) && fails('sin(A)+cos(A)', '1') && identity('sin(A)^2+cos(A)^2', '1') > 10 && identity('1+tan(A)^2', 'sec(A)^2') > 10 && identity('1+cot(A)^2', 'cosec(A)^2') > 10, 'only (c) is false at all 11 angles'); C.key('c'); });

const r13 = fromTan(8, 15);
Q('m13', mk.mcq({ stem: r`If $\tan\theta = \dfrac{8}{15}$ for an acute angle $\theta$, then $\dfrac{\cos\theta - \sin\theta}{\cos\theta + \sin\theta}$ is`, opts: [r`$\dfrac{7}{23}$`, r`$\dfrac{23}{7}$`, r`$-\dfrac{7}{23}$`, r`$\dfrac{7}{15}$`], key: 'a', sol: r`With $\sin\theta = \dfrac{8}{17}$ and $\cos\theta = \dfrac{15}{17}$ (from $1 + \tan^2\theta = \sec^2\theta$), the value is $\dfrac{15 - 8}{15 + 8} = \dfrac{7}{23}$. Option (b) inverts it.`, d: 3, c: 'application', t: [3], time: 100 }), (C) => { C.which([r`$\dfrac{7}{23}$`, r`$\dfrac{23}{7}$`, r`$-\dfrac{7}{23}$`, r`$\dfrac{7}{15}$`], d(tx(G('(cos(T)-sin(T))/(cos(T)+sin(T))', r13)))); C.assert(tx(G('sin(T)', r13)) === r`\dfrac{8}{17}` && tx(G('cos(T)', r13)) === r`\dfrac{15}{17}` && 15 - 8 === 7 && 15 + 8 === 23, 'sin and cos'); });

const r14 = fromSec(25, 7);
Q('m14', mk.mcq({ stem: r`When $\sec\theta = \dfrac{25}{7}$ and $\theta$ is acute, $\cot\theta$ is`, opts: [r`$\dfrac{7}{24}$`, r`$\dfrac{24}{7}$`, r`$\dfrac{25}{24}$`, r`$\dfrac{7}{25}$`], key: 'a', sol: r`$\tan^2\theta = \sec^2\theta - 1 = \dfrac{625}{49} - 1 = \dfrac{576}{49}$, so $\tan\theta = \dfrac{24}{7}$ and $\cot\theta = \dfrac{7}{24}$. Option (b) is $\tan\theta$.`, d: 2, c: 'application', t: [1], time: 75 }), (C) => { C.which([r`$\dfrac{7}{24}$`, r`$\dfrac{24}{7}$`, r`$\dfrac{25}{24}$`, r`$\dfrac{7}{25}$`], d(tx(G('cot(T)', r14)))); C.assert(tx(G('tan(T)', r14)) === r`\dfrac{24}{7}` && tx(G('cos(T)', r14)) === r`\dfrac{7}{25}` && 625 - 49 === 576, 'distractors'); });

Q('m15', mk.mcq({ stem: r`A point is described by $x = a\cos\theta$ and $y = a\sin\theta$, where $a$ is a positive constant. Then $x^2 + y^2$ equals`, opts: [r`$a^2$`, '$a$', r`$2a^2$`, r`$a^2\sin\theta\cos\theta$`], key: 'a', sol: r`$x^2 + y^2 = a^2\cos^2\theta + a^2\sin^2\theta = a^2(\cos^2\theta + \sin^2\theta) = a^2$.`, d: 2, c: 'understanding', t: [3], time: 60 }), (C) => { const vars = { a: 3 }; C.assert(identity('(a*cos(A))^2+(a*sin(A))^2', 'a^2', { vars }) > 10 && fails('(a*cos(A))^2+(a*sin(A))^2', '2*a^2', [30, 45, 60], vars) && fails('(a*cos(A))^2+(a*sin(A))^2', 'a^2*sin(A)*cos(A)', [30, 45, 60], vars) && fails('(a*cos(A))^2+(a*sin(A))^2', 'a', [30, 45, 60], vars), 'only a^2'); C.key('a'); });

Q('m16', mk.mcq({ stem: r`For an acute angle $\theta$, which expression is equal to $\dfrac{1 + \sin\theta}{\cos\theta}$?`, opts: [r`$\dfrac{\cos\theta}{1 - \sin\theta}$`, r`$\dfrac{\cos\theta}{1 + \sin\theta}$`, r`$\sec\theta - \tan\theta$`, r`$\sin\theta + \cos\theta$`], key: 'a', sol: r`Multiply the top and bottom of $\dfrac{1 + \sin\theta}{\cos\theta}$ by $1 - \sin\theta$: $\dfrac{1 - \sin^2\theta}{\cos\theta(1 - \sin\theta)} = \dfrac{\cos\theta}{1 - \sin\theta}$. Options (b) and (c) equal the reciprocal of the given fraction, which is not the fraction itself.`, d: 3, c: 'analysis', t: [2], time: 90 }), (C) => { C.assert(one(only('(1+sin(A))/cos(A)', ['cos(A)/(1-sin(A))', 'cos(A)/(1+sin(A))', 'sec(A)-tan(A)', 'sin(A)+cos(A)']), 0), 'only (a)'); C.assert(identity('sec(A)-tan(A)', 'cos(A)/(1+sin(A))') > 10, '(b) and (c) are the same fraction'); C.key('a'); });

Q('m17', mk.mcq({ stem: r`If $\sin 3A = \cos(A - 26^\circ)$, where $3A$ is acute, then $A$ is`, opts: [r`$29^\circ$`, r`$16^\circ$`, r`$58^\circ$`, r`$31^\circ$`], key: 'a', sol: r`$\sin 3A = \cos(90^\circ - 3A)$, so $90^\circ - 3A = A - 26^\circ$, giving $4A = 116^\circ$ and $A = 29^\circ$. Check: $3A = 87^\circ$ and $\cos 3^\circ = \sin 87^\circ$.`, d: 3, c: 'application', t: [3], time: 90 }), (C) => { const f = (A) => Fl('sin(3*A)-cos(A-26)', { A }); C.assert(close(f(29), 0) && ![16, 58, 31].some((A) => close(f(A), 0)) && 3 * 29 === 87 && 4 * 29 === 116, 'A = 29'); C.sol([29, 116, 87]); });

Q('m18', mk.mcq({ stem: r`For which acute angle $x$ does $\sec x = \operatorname{cosec}(x - 30^\circ)$ hold?`, opts: [r`$60^\circ$`, r`$45^\circ$`, r`$30^\circ$`, r`$75^\circ$`], key: 'a', sol: r`$\sec x = \operatorname{cosec}(90^\circ - x)$, so $90^\circ - x = x - 30^\circ$, giving $2x = 120^\circ$ and $x = 60^\circ$. Check: $\sec 60^\circ = 2 = \operatorname{cosec} 30^\circ$.`, d: 2, c: 'application', t: [3], time: 75 }), (C) => { const f = (A) => Fl('sec(A)-cosec(A-30)', { A }); C.assert(close(f(60), 0) && ![45, 30, 75].some((A) => (A > 30 ? close(f(A), 0) : false)) && val('sec(A)', { A: 60 }) === 2 && val('cosec(A)', { A: 30 }) === 2, 'x = 60'); C.sol([60, 120, 2]); });

Q('m19', mk.mcq({ stem: r`Given $\cos\theta = \dfrac{4}{5}$ with $\theta$ acute, the value of $\dfrac{1}{1 + \sin\theta} + \dfrac{1}{1 - \sin\theta}$ is`, opts: [r`$\dfrac{25}{8}$`, r`$\dfrac{8}{25}$`, r`$\dfrac{5}{2}$`, r`$\dfrac{25}{16}$`], key: 'a', sol: r`Adding the fractions gives $\dfrac{2}{1 - \sin^2\theta} = \dfrac{2}{\cos^2\theta} = \dfrac{2}{16/25} = \dfrac{25}{8}$. Option (d) loses the factor $2$.`, d: 3, c: 'application', t: [3], time: 90 }), (C) => { const g = fromCos(4, 5); C.which([r`$\dfrac{25}{8}$`, r`$\dfrac{8}{25}$`, r`$\dfrac{5}{2}$`, r`$\dfrac{25}{16}$`], d(tx(G('1/(1+sin(T))+1/(1-sin(T))', g)))); C.assert(tx(G('1/cos(T)^2', g)) === r`\dfrac{25}{16}` && identity('1/(1+sin(A))+1/(1-sin(A))', '2/cos(A)^2') > 10, 'distractor (d) and the shortcut'); });

Q('m20', mk.mcq({ stem: r`For an acute angle $A$, the product $(\sec A + \tan A)(1 - \sin A)$ equals`, opts: [r`$\cos A$`, r`$\sin A$`, r`$\sec A$`, '$1$'], key: 'a', sol: r`$\sec A + \tan A = \dfrac{1 + \sin A}{\cos A}$, so the product is $\dfrac{(1 + \sin A)(1 - \sin A)}{\cos A} = \dfrac{\cos^2 A}{\cos A} = \cos A$.`, d: 3, c: 'application', t: [2], time: 80 }), (C) => { C.assert(one(only('(sec(A)+tan(A))*(1-sin(A))', ['cos(A)', 'sin(A)', 'sec(A)', '1']), 0), 'only (a)'); C.key('a'); });

// =============================================================== Assertion-reason (keys a b c d b a)
Q('ar1', mk.ar({ a: r`For every acute angle $A$, $1 + \cot^2 A = \operatorname{cosec}^2 A$.`, r: r`Dividing $\sin^2 A + \cos^2 A = 1$ by $\sin^2 A$ gives $1 + \cot^2 A = \operatorname{cosec}^2 A$.`, key: 'a', sol: r`R is exactly the derivation of A: both statements are true and R explains A.`, d: 2, c: 'understanding', t: [1] }), (C) => { C.assert(identity('1+cot(A)^2', 'cosec(A)^2') > 10 && identity('(sin(A)^2+cos(A)^2)/sin(A)^2', '1+cot(A)^2') > 10, 'A and R true'); C.key('a'); });
Q('ar2', mk.ar({ a: r`$\sin 20^\circ = \cos 70^\circ$.`, r: r`$\sin^2\theta + \cos^2\theta = 1$ for every angle $\theta$ for which the ratios are defined.`, key: 'b', sol: r`A is true because $20^\circ + 70^\circ = 90^\circ$ (complementary angles). R is also true, but it says nothing about complementary angles, so it does not explain A.`, d: 2, c: 'understanding', t: [3] }), (C) => { C.assert(close(Fl('sin(A)', { A: 20 }), Fl('cos(A)', { A: 70 })) && identity('sin(A)^2+cos(A)^2', '1') > 10, 'A and R true'); C.key('b'); });
Q('ar3', mk.ar({ a: r`For every acute angle $A$, $\tan^2 A - \sec^2 A = -1$.`, r: r`The identity $1 + \tan^2 A = \sec^2 A$ holds only when $A = 45^\circ$.`, key: 'c', sol: r`A is true: rearranging $1 + \tan^2 A = \sec^2 A$ gives $\tan^2 A - \sec^2 A = -1$. R is false: the identity holds for every angle $0^\circ \le A < 90^\circ$ (for example $\tan 30^\circ$ and $\sec 30^\circ$ also satisfy it).`, d: 2, c: 'understanding', t: [1] }), (C) => { C.assert(identity('tan(A)^2-sec(A)^2', '-1') > 10 && identity('1+tan(A)^2', 'sec(A)^2', { exact: [30, 60] }) > 10, 'A true, R false: identity holds at 30 and 60 too'); C.key('c'); });
const r04b = fromSin(4, 5);
Q('ar4', mk.ar({ a: r`If $\sin\theta = \dfrac{4}{5}$ for an acute angle $\theta$, then $\cos\theta = \dfrac{1}{5}$.`, r: r`For every angle $\theta$, $\sin^2\theta + \cos^2\theta = 1$.`, key: 'd', sol: r`R is true. By R, $\cos^2\theta = 1 - \dfrac{16}{25} = \dfrac{9}{25}$, so $\cos\theta = \dfrac{3}{5}$, not $\dfrac{1}{5}$. A is false.`, d: 2, c: 'understanding', t: [1] }), (C) => { C.assert(tx(G('cos(T)', r04b)) === r`\dfrac{3}{5}` && tx(G('cos(T)', r04b)) !== r`\dfrac{1}{5}`, 'A false (cos = 3/5)'); C.key('d'); });
Q('ar5', mk.ar({ a: r`$\sec^2 30^\circ - \tan^2 30^\circ = 1$.`, r: r`$\tan 30^\circ = \dfrac{1}{\sqrt{3}}$.`, key: 'b', sol: r`A is true: $\sec^2 30^\circ = \dfrac{4}{3}$ and $\tan^2 30^\circ = \dfrac{1}{3}$, and $\dfrac{4}{3} - \dfrac{1}{3} = 1$. R is a true value, but A is an instance of the identity $\sec^2\theta - \tan^2\theta = 1$, so R does not explain A.`, d: 2, c: 'understanding', t: [1] }), (C) => { C.assert(val('sec(30)^2-tan(30)^2') === 1 && tx(E('tan(30)')) === String.raw`\dfrac{\sqrt{3}}{3}`, 'A and R true'); C.assert(tx(E('sec(30)^2')) === r`\dfrac{4}{3}` && tx(E('tan(30)^2')) === r`\dfrac{1}{3}`, 'values'); C.key('b'); });
Q('ar6', mk.ar({ a: r`$(\sin A + \cos A)^2 + (\sin A - \cos A)^2 = 2$ for every angle $A$.`, r: r`When the two squares are expanded, the terms $2\sin A\cos A$ cancel and $\sin^2 A + \cos^2 A = 1$ is used twice.`, key: 'a', sol: r`Expanding, the sum is $2\sin^2 A + 2\cos^2 A = 2(\sin^2 A + \cos^2 A) = 2$. R describes exactly this working, so both are true and R explains A.`, d: 3, c: 'analysis', t: [3] }), (C) => { C.assert(identity('(sin(A)+cos(A))^2+(sin(A)-cos(A))^2', '2') > 10 && identity('(sin(A)+cos(A))^2+(sin(A)-cos(A))^2', '2*sin(A)^2+2*cos(A)^2') > 10, 'A true; R is its working'); C.key('a'); });

// =============================================================== True / false (5)
Q('tf1', mk.tf({ stem: r`Because $\sin^2\theta + \cos^2\theta = 1$, we may conclude that $\sin\theta + \cos\theta = 1$ for every acute angle $\theta$.`, key: 'f', sol: r`False. Squares adding to $1$ does not make the numbers themselves add to $1$: at $\theta = 45^\circ$, $\sin\theta + \cos\theta = \sqrt{2} \ne 1$.`, d: 2, c: 'understanding', t: [1] }), (C) => { C.assert(tx(E('sin(A)+cos(A)', { A: 45 })) === r`\sqrt{2}` && fails('sin(A)+cos(A)', '1'), 'false at 45'); C.key('f'); });
Q('tf2', mk.tf({ stem: r`The identity $1 + \tan^2 A = \sec^2 A$ is true at $A = 45^\circ$.`, key: 't', sol: r`$1 + \tan^2 45^\circ = 1 + 1 = 2$ and $\sec^2 45^\circ = (\sqrt{2})^2 = 2$.`, d: 1, c: 'understanding', t: [1] }), (C) => { C.assert(val('1+tan(A)^2', { A: 45 }) === 2 && val('sec(A)^2', { A: 45 }) === 2, 'both 2'); C.key('t'); });
Q('tf3', mk.tf({ stem: r`If $A$ and $B$ are the two acute angles of a right-angled triangle, then $\sin A = \cos B$.`, key: 't', sol: r`$A + B = 90^\circ$, so $\sin A = \sin(90^\circ - B) = \cos B$.`, d: 1, c: 'recall', t: [3] }), (C) => { C.assert(identity('sin(A)', 'cos(90-A)') > 10, 'complementary'); C.key('t'); });
Q('tf4', mk.tf({ stem: r`The relation $1 + \tan^2 A = \sec^2 A$ also holds at $A = 0^\circ$.`, key: 't', sol: r`$\tan 0^\circ = 0$ and $\sec 0^\circ = 1$, so $1 + 0 = 1$ and the identity holds at $0^\circ$.`, d: 2, c: 'understanding', t: [1] }), (C) => { C.assert(val('1+tan(A)^2', { A: 0 }) === 1 && val('sec(A)^2', { A: 0 }) === 1, 'both 1'); C.key('t'); });
Q('tf5', mk.tf({ stem: r`The relation $1 + \cot^2 A = \operatorname{cosec}^2 A$ is valid at $A = 0^\circ$.`, key: 'f', sol: r`False: $\cot 0^\circ$ and $\operatorname{cosec} 0^\circ$ are not defined (division by $\sin 0^\circ = 0$), so the identity cannot be used at $0^\circ$.`, d: 2, c: 'understanding', t: [1] }), (C) => { let threw = false; try { E('cot(A)', { A: 0 }); } catch { threw = true; } C.assert(threw, 'cot 0 undefined'); C.key('f'); });

// =============================================================== Fill in the blank (6)
Q('fb1', mk.fill({ stem: r`The value of $\tan 20^\circ \cdot \tan 70^\circ$ is ___.`, acc: [['1']], sol: r`$\tan 70^\circ = \cot 20^\circ$, so $\tan 20^\circ \cdot \cot 20^\circ = 1$.`, d: 1, c: 'understanding', t: [3] }), (C) => { C.assert(close(Fl('tan(20)*tan(70)'), 1), 'value 1'); C.blank(1); });
const r02 = fromCos(7, 25);
Q('fb2', mk.fill({ stem: r`If $\cos A = \dfrac{7}{25}$ and $A$ is acute, then $\sin A =$ ___.`, acc: [['24/25', '0.96']], sol: r`$\sin^2 A = 1 - \dfrac{49}{625} = \dfrac{576}{625}$, so $\sin A = \dfrac{24}{25}$, that is 24/25.`, d: 1, c: 'understanding', t: [1] }), (C) => { C.assert(tx(G('sin(T)', r02)) === r`\dfrac{24}{25}` && 625 - 49 === 576, 'sin A'); C.blank(24 / 25); });
const r03b = fromCosec(41, 9);
Q('fb3', mk.fill({ stem: r`When $\operatorname{cosec}\theta = \dfrac{41}{9}$ for an acute angle $\theta$, $\cot\theta =$ ___.`, acc: [['40/9']], sol: r`$\cot^2\theta = \operatorname{cosec}^2\theta - 1 = \dfrac{1681}{81} - 1 = \dfrac{1600}{81}$, so $\cot\theta = \dfrac{40}{9}$, that is 40/9.`, d: 2, c: 'application', t: [1] }), (C) => { C.assert(tx(G('cot(T)', r03b)) === r`\dfrac{40}{9}` && 1681 - 81 === 1600, 'cot'); C.blank(40 / 9); });
Q('fb4', mk.fill({ stem: r`A student reduces $\sin 35^\circ - \cos 55^\circ$ with a complementary-angle rule. The result is ___.`, acc: [['0']], sol: r`$\cos 55^\circ = \sin(90^\circ - 55^\circ) = \sin 35^\circ$, so the difference is $0$.`, d: 1, c: 'understanding', t: [3] }), (C) => { C.assert(close(Fl('sin(35)-cos(55)'), 0), 'value 0'); C.blank(0); });
Q('fb5', mk.fill({ stem: r`The product $\tan 5^\circ \tan 25^\circ \tan 45^\circ \tan 65^\circ \tan 85^\circ$ equals ___.`, acc: [['1']], sol: r`Pair $\tan 5^\circ$ with $\tan 85^\circ$ and $\tan 25^\circ$ with $\tan 65^\circ$: each pair multiplies to $1$, and $\tan 45^\circ = 1$, so the product is $1$.`, d: 2, c: 'application', t: [3] }), (C) => { C.assert(close(Fl('tan(5)*tan(25)*tan(45)*tan(65)*tan(85)'), 1) && close(Fl('tan(5)*tan(85)'), 1) && close(Fl('tan(25)*tan(65)'), 1), 'value 1'); C.blank(1); });
Q('fb6', mk.fill({ stem: r`Dividing $\sin^2 A + \cos^2 A = 1$ throughout by $\cos^2 A$ gives $1 + \tan^2 A =$ ___.`, acc: [['sec^2 A', 'sec²A']], sol: r`$1 + \dfrac{\sin^2 A}{\cos^2 A} = \dfrac{1}{\cos^2 A}$, that is $1 + \tan^2 A = \sec^2 A$.`, d: 1, c: 'recall', t: [1] }), (C) => { C.assert(identity('(sin(A)^2+cos(A)^2)/cos(A)^2', 'sec(A)^2') > 10, 'sec^2'); C.blank('sec^2 A'); });

// =============================================================== Numerical (6)
const r01 = fromSin(4, 5);
Q('n01', mk.num({ stem: r`If $\sin\theta = 0.8$ for an acute angle $\theta$, find the value of $\dfrac{1}{1 - \cos\theta} + \dfrac{1}{1 + \cos\theta}$.`, value: 3.125, sol: r`The sum of the fractions is $\dfrac{2}{1 - \cos^2\theta} = \dfrac{2}{\sin^2\theta} = \dfrac{2}{0.64} = 3.125$.`, scheme: [['Sum = 2 / sin²θ', 1], ['Value 3.125', 1]], d: 3, c: 'application', t: [3], time: 90, marks: 2 }), (C) => { const v = G('1/(1-cos(T))+1/(1+cos(T))', r01); C.val(T.num(v)); C.assert(tx(G('cos(T)', r01)) === r`\dfrac{3}{5}` && identity('1/(1-cos(A))+1/(1+cos(A))', '2/sin(A)^2') > 10 && 2 / 0.64 === 3.125, 'expression and shortcut'); });
Q('n02', mk.num({ stem: r`Using the values of the standard angles, evaluate $3\cot^2 30^\circ - \operatorname{cosec}^2 45^\circ + 2\sin^2 60^\circ$.`, value: 8.5, sol: r`$\cot^2 30^\circ = 3$, $\operatorname{cosec}^2 45^\circ = 2$ and $\sin^2 60^\circ = \dfrac{3}{4}$, so the value is $9 - 2 + 1.5 = 8.5$.`, scheme: [['Values 3, 2 and 3/4', 1], ['8.5', 1]], d: 2, c: 'understanding', t: [3], time: 90, marks: 2 }), (C) => { C.val(val('3*cot(30)^2-cosec(45)^2+2*sin(60)^2')); C.assert(val('cot(30)^2') === 3 && val('cosec(45)^2') === 2 && tx(E('sin(60)^2')) === r`\dfrac{3}{4}`, 'exact values'); });
Q('n03', mk.num({ stem: r`Find the value of $4\cos^2 52^\circ + 4\cos^2 38^\circ - \tan 24^\circ\tan 66^\circ\sin 90^\circ$.`, value: 3, sol: r`$\cos 38^\circ = \sin 52^\circ$, so $4(\cos^2 52^\circ + \sin^2 52^\circ) = 4$. Also $\tan 24^\circ\tan 66^\circ = 1$ and $\sin 90^\circ = 1$. The value is $4 - 1 = 3$.`, scheme: [['4 from the first two terms', 1], ['Third term 1', 1], ['3', 1]], d: 3, c: 'application', t: [3], time: 100, marks: 3 }), (C) => { C.val(Math.round(Fl('4*cos(52)^2+4*cos(38)^2-tan(24)*tan(66)*sin(90)'))); C.assert(close(Fl('4*cos(52)^2+4*cos(38)^2-tan(24)*tan(66)*sin(90)'), 3) && close(Fl('tan(24)*tan(66)'), 1), 'exactly 3'); });
Q('n04', mk.num({ stem: r`Find the acute angle $\theta$, in degrees, for which $\tan 2\theta = \cot(\theta + 18^\circ)$.`, value: 24, sol: r`$\cot(\theta + 18^\circ) = \tan(90^\circ - \theta - 18^\circ)$, so $2\theta = 72^\circ - \theta$, giving $3\theta = 72^\circ$ and $\theta = 24$.`, scheme: [['Complementary form of cot', 1], ['θ = 24', 1]], d: 3, c: 'application', t: [3], time: 90, marks: 2, unit: '°' }), (C) => { const f = (A) => Fl('tan(2*A)-cot(A+18)', { A }); C.val(24); C.assert(close(f(24), 0) && ![20, 30, 18, 36].some((A) => close(f(A), 0)) && 90 - 24 - 18 === 48 && 2 * 24 === 48, 'check at 24 degrees: tan 48 = cot 42'); });
Q('n05', mk.num({ stem: r`A point on a drawing board has coordinates $(x, y) = (r\cos\theta,\ r\sin\theta)$ with $r > 0$. If $x = 12$ and $y = 5$, find $r$.`, value: 13, sol: r`$r^2 = r^2(\cos^2\theta + \sin^2\theta) = x^2 + y^2 = 144 + 25 = 169$, so $r = 13$.`, scheme: [['x² + y² = r²', 1], ['r = 13', 1]], d: 2, c: 'application', t: [3], time: 75, marks: 2 }), (C) => { const th = Math.atan2(5, 12) * 180 / Math.PI; C.val(13); C.assert(close(13 * Math.cos(th * Math.PI / 180), 12, 1e-9) && close(13 * Math.sin(th * Math.PI / 180), 5, 1e-9) && 144 + 25 === 169, 'r = 13 gives (12, 5)'); });
const r06 = fromCot(3, 4);
Q('n06', mk.num({ stem: r`The cotangent of an acute angle $\theta$ satisfies $4\cot\theta = 3$. Using an identity to get the sine and cosine, work out $10\sin\theta + 5\cos\theta$.`, value: 11, sol: r`$\cot\theta = \dfrac{3}{4}$ gives $\operatorname{cosec}^2\theta = 1 + \dfrac{9}{16} = \dfrac{25}{16}$, so $\sin\theta = \dfrac{4}{5}$ and $\cos\theta = \dfrac{3}{5}$. Then $10\sin\theta + 5\cos\theta = 8 + 3 = 11$.`, scheme: [['sin θ = 4/5, cos θ = 3/5', 1], ['11', 1]], d: 2, c: 'application', t: [1, 3], time: 90, marks: 2 }), (C) => { C.val(T.num(G('10*sin(T)+5*cos(T)', r06))); C.assert(tx(G('sin(T)', r06)) === r`\dfrac{4}{5}` && tx(G('cos(T)', r06)) === r`\dfrac{3}{5}`, 'sin and cos'); });

// =============================================================== Short answer, 2 marks (4)
Q('s201', mk.short({ marks: 2, stem: r`Rearrange the identities for an acute angle $\theta$ to write (a) $\cos^2\theta$ in terms of $\sin\theta$ (b) $\sec^2\theta - 1$ in terms of $\tan\theta$.`, model: J([r`(a) From $\sin^2\theta + \cos^2\theta = 1$: $\cos^2\theta = 1 - \sin^2\theta$.`, r`(b) From $1 + \tan^2\theta = \sec^2\theta$: $\sec^2\theta - 1 = \tan^2\theta$.`]), sol: 'Move the terms of each identity to isolate what is asked.', scheme: [['(a) 1 − sin²θ', 1], ['(b) tan²θ', 1]], d: 1, c: 'recall', t: [1], time: 60 }), (C) => { C.assert(identity('cos(A)^2', '1-sin(A)^2') > 10 && identity('sec(A)^2-1', 'tan(A)^2') > 10, '(a) and (b)'); C.model([r`1 - \sin^2\theta`, r`\tan^2\theta`]); });
const rp = { a: 63, b: 16, h: 65 };
Q('s202', mk.short({ marks: 2, stem: r`In triangle $PQR$ right-angled at $Q$, $PQ = 63$ cm and $QR = 16$ cm. Find $PR$, then show that $1 + \tan^2 P = \sec^2 P$ for this triangle.`, model: J([r`$PR^2 = 63^2 + 16^2 = 3969 + 256 = 4225$, so $PR = 65$ cm.`, r`$\tan P = \dfrac{16}{63}$ and $\sec P = \dfrac{65}{63}$.`, r`$1 + \tan^2 P = 1 + \dfrac{256}{3969} = \dfrac{4225}{3969} = \sec^2 P$.`]), sol: 'Use Pythagoras for the hypotenuse, then compare both sides of the identity.', scheme: [['PR = 65 cm', 1], ['Both sides equal 4225/3969', 1]], d: 2, c: 'application', t: [1], time: 100 }), (C) => { const g = fromTan(16, 63); C.assert(rp.a ** 2 + rp.b ** 2 === rp.h ** 2 && 3969 + 256 === 4225 && T.eq(T.add(1, T.pow(G('tan(T)', g), 2)), T.pow(G('sec(T)', g), 2)) && tx(G('tan(T)', g)) === String.raw`\dfrac{16}{63}` && tx(G('sec(T)', g)) === String.raw`\dfrac{65}{63}`, 'triangle and identity'); C.model([65, 4225, 3969]); });
Q('s203', mk.short({ marks: 2, stem: r`A workbook claims that some acute angle $\theta$ has both $\sin\theta = \dfrac{3}{4}$ and $\cos\theta = \dfrac{2}{3}$. Use an identity to decide whether this is possible.`, model: J([r`If both were true, $\sin^2\theta + \cos^2\theta = \dfrac{9}{16} + \dfrac{4}{9} = \dfrac{81 + 64}{144} = \dfrac{145}{144}$.`, r`This is not $1$, which contradicts $\sin^2\theta + \cos^2\theta = 1$. So no such angle exists.`]), sol: 'Test the pair of values in sin²θ + cos²θ = 1.', scheme: [['Sum of squares 145/144', 1], ['Not 1, so impossible', 1]], d: 2, c: 'analysis', t: [1], time: 90 }), (C) => { C.assert(T.eq(E('x^2+y^2', { x: T.div(3, 4), y: T.div(2, 3) }), T.div(145, 144)) && 81 + 64 === 145, 'sum is 145/144'); C.model([r`\dfrac{145}{144}`, 145, 144]); });
Q('s204', mk.short({ marks: 2, stem: r`Simplify $\cos\theta\sqrt{\sec^2\theta - 1}$ for an acute angle $\theta$, giving the answer as a single trigonometric ratio.`, model: J([r`$\sec^2\theta - 1 = \tan^2\theta$, so $\sqrt{\sec^2\theta - 1} = \tan\theta$ (positive, as $\theta$ is acute).`, r`$\cos\theta \times \tan\theta = \cos\theta \times \dfrac{\sin\theta}{\cos\theta} = \sin\theta$.`]), sol: 'Replace sec²θ − 1 by tan²θ, take the positive root, and write tan as sin over cos.', scheme: [['sqrt = tan θ', 1], ['Result sin θ', 1]], d: 2, c: 'application', t: [3], time: 80 }), (C) => { C.assert(chain('cos(A)*tan(A)', 'cos(A)*sin(A)/cos(A)', 'sin(A)') > 0 && FL.every((A) => close(Math.cos((A * Math.PI) / 180) * Math.sqrt(Fl('sec(A)^2-1', { A })), Fl('sin(A)', { A }))), 'result sin'); C.model([r`\sin\theta`, r`\tan\theta`]); });

// =============================================================== Short answer, 3 marks (5)
Q('s301', mk.short({ marks: 3, stem: r`Multiplying $1 - \cos\theta$ by $1 + \sec\theta$ always gives the product of sine and tangent. Prove that $(1 - \cos\theta)(1 + \sec\theta) = \sin\theta\tan\theta$.`, model: J([r`LHS $= (1 - \cos\theta)\left(1 + \dfrac{1}{\cos\theta}\right) = \dfrac{(1 - \cos\theta)(\cos\theta + 1)}{\cos\theta}$.`, r`$= \dfrac{1 - \cos^2\theta}{\cos\theta} = \dfrac{\sin^2\theta}{\cos\theta}$.`, r`$= \sin\theta \times \dfrac{\sin\theta}{\cos\theta} = \sin\theta\tan\theta = $ RHS.`]), sol: 'Write sec in terms of cos, combine, and use 1 − cos² = sin².', scheme: [['sec θ = 1/cos θ, combined', 1], ['(1 − cos θ)(1 + cos θ) = sin² θ', 1], ['= sin θ tan θ', 1]], d: 2, c: 'application', t: [2], time: 150 }), (C) => { C.assert(chain('(1-cos(A))*(1+sec(A))', '(1-cos(A))*(cos(A)+1)/cos(A)', '(1-cos(A)^2)/cos(A)', 'sin(A)^2/cos(A)', 'sin(A)*tan(A)') > 0, 'every step equal'); C.assert(fails('(1-cos(A))*(1+sec(A))', 'sin(A)*cot(A)'), 'a wrong right-hand side fails'); C.model([r`\sin^2\theta`]); });
Q('s302', mk.short({ marks: 3, stem: r`The ratio $\dfrac{1 + \cos A}{1 - \cos A}$ can be rewritten as a perfect square of cosecant and cotangent. Prove that $\dfrac{1 + \cos A}{1 - \cos A} = (\operatorname{cosec} A + \cot A)^2$.`, model: J([r`RHS $= \left(\dfrac{1}{\sin A} + \dfrac{\cos A}{\sin A}\right)^2 = \dfrac{(1 + \cos A)^2}{\sin^2 A}$.`, r`$= \dfrac{(1 + \cos A)^2}{1 - \cos^2 A} = \dfrac{(1 + \cos A)^2}{(1 - \cos A)(1 + \cos A)}$.`, r`$= \dfrac{1 + \cos A}{1 - \cos A} = $ LHS.`]), sol: 'Start with the right-hand side, write cosec and cot with sin and cos, then use sin² A = 1 − cos² A.', scheme: [['Combined over sin A, squared', 1], ['sin² A = (1 − cos A)(1 + cos A)', 1], ['Cancelled to LHS', 1]], d: 3, c: 'application', t: [2], time: 150 }), (C) => { C.assert(chain('(cosec(A)+cot(A))^2', '(1+cos(A))^2/sin(A)^2', '(1+cos(A))^2/(1-cos(A)^2)', '(1+cos(A))^2/((1-cos(A))*(1+cos(A)))', '(1+cos(A))/(1-cos(A))') > 0, 'every step equal'); C.model([r`(1 + \cos A)^2`]); });
Q('s303', mk.short({ marks: 3, stem: r`The difference between $\cot^2 A$ and $\cos^2 A$ equals the product of the same two quantities. Show that $\cot^2 A - \cos^2 A = \cot^2 A\cos^2 A$.`, model: J([r`LHS $= \dfrac{\cos^2 A}{\sin^2 A} - \cos^2 A = \cos^2 A\left(\dfrac{1}{\sin^2 A} - 1\right)$.`, r`$= \cos^2 A \times \dfrac{1 - \sin^2 A}{\sin^2 A} = \cos^2 A \times \dfrac{\cos^2 A}{\sin^2 A}$.`, r`$= \cos^2 A\cot^2 A = $ RHS.`]), sol: 'Factor out cos² A, combine the bracket, and use 1 − sin² A = cos² A.', scheme: [['cos² A taken out', 1], ['1 − sin² A = cos² A', 1], ['= cos² A cot² A', 1]], d: 2, c: 'application', t: [2], time: 150 }), (C) => { C.assert(chain('cot(A)^2-cos(A)^2', 'cos(A)^2*(1/sin(A)^2-1)', 'cos(A)^2*(1-sin(A)^2)/sin(A)^2', 'cos(A)^2*cos(A)^2/sin(A)^2', 'cos(A)^2*cot(A)^2') > 0, 'every step equal'); C.model([r`\cos^2 A`]); });
const r304 = fromSec(17, 8);
Q('s304', mk.short({ marks: 3, stem: r`Given $\sec\theta = \dfrac{17}{8}$ for an acute angle $\theta$, find the value of $\dfrac{\tan\theta - \sin\theta}{\tan\theta + \sin\theta}$.`, model: J([r`$\tan^2\theta = \sec^2\theta - 1 = \dfrac{289}{64} - 1 = \dfrac{225}{64}$, so $\tan\theta = \dfrac{15}{8}$.`, r`$\cos\theta = \dfrac{8}{17}$ and $\sin\theta = \tan\theta\cos\theta = \dfrac{15}{8} \times \dfrac{8}{17} = \dfrac{15}{17}$.`, r`$\dfrac{\tan\theta - \sin\theta}{\tan\theta + \sin\theta} = \dfrac{\frac{15}{8} - \frac{15}{17}}{\frac{15}{8} + \frac{15}{17}} = \dfrac{17 - 8}{17 + 8} = \dfrac{9}{25}$.`]), sol: 'Find tan and sin from the identity, then substitute; the common factor 15 cancels.', scheme: [['tan θ = 15/8', 1], ['sin θ = 15/17', 1], ['9/25', 1]], d: 3, c: 'application', t: [3], time: 160 }), (C) => { C.assert(tx(G('tan(T)', r304)) === r`\dfrac{15}{8}` && tx(G('sin(T)', r304)) === r`\dfrac{15}{17}` && tx(G('(tan(T)-sin(T))/(tan(T)+sin(T))', r304)) === r`\dfrac{9}{25}` && 289 - 64 === 225, 'exact value 9/25'); C.model([r`\dfrac{9}{25}`, r`\dfrac{15}{8}`, r`\dfrac{15}{17}`]); });
Q('s305', mk.short({ marks: 3, stem: r`Use the complementary-angle rules to evaluate $\dfrac{\sin 63^\circ}{\cos 27^\circ} + \dfrac{\cot 12^\circ}{\tan 78^\circ} - 3\sec 51^\circ\sin 39^\circ$.`, model: J([r`$\sin 63^\circ = \cos 27^\circ$, so $\dfrac{\sin 63^\circ}{\cos 27^\circ} = 1$.`, r`$\cot 12^\circ = \tan 78^\circ$, so $\dfrac{\cot 12^\circ}{\tan 78^\circ} = 1$.`, r`$\sin 39^\circ = \cos 51^\circ$, so $\sec 51^\circ\sin 39^\circ = 1$. The value is $1 + 1 - 3 = -1$.`]), sol: 'Convert each term to a ratio of the same angle; every term becomes 1.', scheme: [['First term 1', 1], ['Second term 1', 1], ['Third term and −1', 1]], d: 3, c: 'application', t: [3], time: 150 }), (C) => { C.assert(close(Fl('sin(63)/cos(27)+cot(12)/tan(78)-3*sec(51)*sin(39)'), -1) && close(Fl('sec(51)*sin(39)'), 1), 'value -1'); C.model([1, 3, -1]); });

// =============================================================== Short answer, 4 marks (6)
Q('s401', mk.short({ marks: 4, stem: r`Two fractions with $\sin A$ and $1 + \cos A$ in their denominators combine into a multiple of $\operatorname{cosec} A$. Prove that $\dfrac{\sin A}{1 + \cos A} + \dfrac{1 + \cos A}{\sin A} = 2\operatorname{cosec} A$.`, model: J([r`LHS $= \dfrac{\sin^2 A + (1 + \cos A)^2}{\sin A(1 + \cos A)}$.`, r`Expand the numerator: $\sin^2 A + 1 + 2\cos A + \cos^2 A = 2 + 2\cos A$, using $\sin^2 A + \cos^2 A = 1$.`, r`$= \dfrac{2(1 + \cos A)}{\sin A(1 + \cos A)}$.`, r`$= \dfrac{2}{\sin A} = 2\operatorname{cosec} A = $ RHS.`]), sol: 'Add the fractions over a common denominator, simplify the numerator with sin² + cos² = 1, then cancel 1 + cos A.', scheme: [['Common denominator', 1], ['Numerator 2 + 2 cos A', 1], ['Factor 1 + cos A cancelled', 1], ['2 cosec A', 1]], d: 3, c: 'application', t: [2], time: 220 }), (C) => { C.assert(chain('sin(A)/(1+cos(A))+(1+cos(A))/sin(A)', '(sin(A)^2+(1+cos(A))^2)/(sin(A)*(1+cos(A)))', '(sin(A)^2+1+2*cos(A)+cos(A)^2)/(sin(A)*(1+cos(A)))', '(2+2*cos(A))/(sin(A)*(1+cos(A)))', '2*(1+cos(A))/(sin(A)*(1+cos(A)))', '2/sin(A)', '2*cosec(A)') > 0, 'every step equal'); C.model([r`2 + 2\cos A`]); });
Q('s402', mk.short({ marks: 4, stem: r`The square of the difference of cosecant and cotangent is a ratio of two simple sums. Show that $(\operatorname{cosec}\theta - \cot\theta)^2 = \dfrac{1 - \cos\theta}{1 + \cos\theta}$.`, model: J([r`LHS $= \left(\dfrac{1}{\sin\theta} - \dfrac{\cos\theta}{\sin\theta}\right)^2 = \dfrac{(1 - \cos\theta)^2}{\sin^2\theta}$.`, r`$\sin^2\theta = 1 - \cos^2\theta = (1 - \cos\theta)(1 + \cos\theta)$.`, r`So LHS $= \dfrac{(1 - \cos\theta)^2}{(1 - \cos\theta)(1 + \cos\theta)}$.`, r`$= \dfrac{1 - \cos\theta}{1 + \cos\theta} = $ RHS.`]), sol: 'Rewrite with sin and cos, replace sin² θ by (1 − cos θ)(1 + cos θ), and cancel.', scheme: [['Expressed with sin and cos', 1], ['sin² θ factorised', 1], ['Substituted', 1], ['Cancelled to RHS', 1]], d: 3, c: 'application', t: [2], time: 220 }), (C) => { C.assert(chain('(cosec(A)-cot(A))^2', '(1-cos(A))^2/sin(A)^2', '(1-cos(A))^2/((1-cos(A))*(1+cos(A)))', '(1-cos(A))/(1+cos(A))') > 0, 'every step equal'); C.model([r`(1 - \cos\theta)^2`]); });
Q('s403', mk.short({ marks: 4, stem: r`The sum of sine and cosine times the sum of tangent and cotangent leaves only reciprocal ratios. Prove that $(\sin A + \cos A)(\tan A + \cot A) = \sec A + \operatorname{cosec} A$.`, model: J([r`$\tan A + \cot A = \dfrac{\sin A}{\cos A} + \dfrac{\cos A}{\sin A} = \dfrac{\sin^2 A + \cos^2 A}{\sin A\cos A} = \dfrac{1}{\sin A\cos A}$.`, r`LHS $= \dfrac{\sin A + \cos A}{\sin A\cos A}$.`, r`$= \dfrac{\sin A}{\sin A\cos A} + \dfrac{\cos A}{\sin A\cos A}$.`, r`$= \dfrac{1}{\cos A} + \dfrac{1}{\sin A} = \sec A + \operatorname{cosec} A = $ RHS.`]), sol: 'Combine tan + cot first using sin² + cos² = 1, then split the fraction.', scheme: [['tan A + cot A as one fraction', 1], ['= 1/(sin A cos A)', 1], ['Fraction split into two', 1], ['sec A + cosec A', 1]], d: 3, c: 'application', t: [2], time: 220 }), (C) => { C.assert(chain('(sin(A)+cos(A))*(tan(A)+cot(A))', '(sin(A)+cos(A))/(sin(A)*cos(A))', 'sin(A)/(sin(A)*cos(A))+cos(A)/(sin(A)*cos(A))', 'sec(A)+cosec(A)') > 0 && identity('tan(A)+cot(A)', '1/(sin(A)*cos(A))') > 10, 'every step equal'); C.model([r`\dfrac{1}{\sin A\cos A}`]); });
Q('s404', mk.short({ marks: 4, stem: r`(a) Prove that $(1 + \tan A)^2 + (1 - \tan A)^2 = 2\sec^2 A$. (b) Hence find the value of the left-hand side when $\tan A = \dfrac{4}{3}$.`, model: J([r`(a) LHS $= (1 + 2\tan A + \tan^2 A) + (1 - 2\tan A + \tan^2 A) = 2 + 2\tan^2 A$.`, r`$= 2(1 + \tan^2 A) = 2\sec^2 A = $ RHS.`, r`(b) With $\tan A = \dfrac{4}{3}$: $2 + 2 \times \dfrac{16}{9} = \dfrac{50}{9}$, and $2\sec^2 A = 2 \times \dfrac{25}{9} = \dfrac{50}{9}$.`, r`The value is $\dfrac{50}{9}$.`]), sol: 'Expand both squares (the middle terms cancel), then use 1 + tan² A = sec² A; for part (b) the identity gives 2 sec² A directly.', scheme: [['(a) Expansion 2 + 2 tan² A', 1], ['(a) 2 sec² A', 1], ['(b) sec² A = 25/9', 1], ['(b) 50/9', 1]], d: 3, c: 'application', t: [2, 3], time: 220 }), (C) => { const g = fromTan(4, 3); C.assert(chain('(1+tan(A))^2+(1-tan(A))^2', '1+2*tan(A)+tan(A)^2+1-2*tan(A)+tan(A)^2', '2+2*tan(A)^2', '2*(1+tan(A)^2)', '2*sec(A)^2') > 0 && tx(G('(1+tan(T))^2+(1-tan(T))^2', g)) === r`\dfrac{50}{9}` && tx(G('2*sec(T)^2', g)) === r`\dfrac{50}{9}`, 'identity and value'); C.model([r`\dfrac{50}{9}`, 9, 25]); });
Q('s405', mk.short({ marks: 4, stem: r`Fourth powers of cosine and sine give a neat result when subtracted. Prove that $\cos^4 A - \sin^4 A = 2\cos^2 A - 1$.`, model: J([r`LHS $= (\cos^2 A - \sin^2 A)(\cos^2 A + \sin^2 A)$, a difference of two squares.`, r`$\cos^2 A + \sin^2 A = 1$, so LHS $= \cos^2 A - \sin^2 A$.`, r`Replace $\sin^2 A$ by $1 - \cos^2 A$: LHS $= \cos^2 A - (1 - \cos^2 A)$.`, r`$= 2\cos^2 A - 1 = $ RHS.`]), sol: 'Factorise as a difference of squares, use sin² + cos² = 1, then eliminate sin² A.', scheme: [['Difference of squares', 1], ['Second factor 1', 1], ['sin² A = 1 − cos² A', 1], ['2 cos² A − 1', 1]], d: 3, c: 'application', t: [2], time: 200 }), (C) => { C.assert(chain('cos(A)^4-sin(A)^4', '(cos(A)^2-sin(A)^2)*(cos(A)^2+sin(A)^2)', 'cos(A)^2-sin(A)^2', 'cos(A)^2-(1-cos(A)^2)', '2*cos(A)^2-1') > 0, 'every step equal'); C.model([r`2\cos^2 A - 1`]); });
const r406 = fromCot(33, 56);
Q('s406', mk.short({ marks: 4, stem: r`For an acute angle $\theta$ with $\cot\theta = \dfrac{33}{56}$, find (a) $\sin\theta$ and $\cos\theta$ (b) the value of $\dfrac{\operatorname{cosec}\theta - \cot\theta}{\operatorname{cosec}\theta + \cot\theta}$.`, model: J([r`(a) $\operatorname{cosec}^2\theta = 1 + \cot^2\theta = 1 + \dfrac{1089}{3136} = \dfrac{4225}{3136}$, so $\operatorname{cosec}\theta = \dfrac{65}{56}$ and $\sin\theta = \dfrac{56}{65}$.`, r`$\cos\theta = \cot\theta\sin\theta = \dfrac{33}{56} \times \dfrac{56}{65} = \dfrac{33}{65}$.`, r`(b) $\dfrac{\operatorname{cosec}\theta - \cot\theta}{\operatorname{cosec}\theta + \cot\theta} = \dfrac{\frac{65}{56} - \frac{33}{56}}{\frac{65}{56} + \frac{33}{56}} = \dfrac{65 - 33}{65 + 33} = \dfrac{32}{98}$.`, r`$= \dfrac{16}{49}$.`]), sol: 'Use 1 + cot² θ = cosec² θ for the sine, then substitute into the fraction.', scheme: [['cosec θ = 65/56, sin θ = 56/65', 1], ['cos θ = 33/65', 1], ['32/98 from the substitution', 1], ['16/49', 1]], d: 3, c: 'application', t: [1, 3], time: 220 }), (C) => { C.assert(tx(G('sin(T)', r406)) === r`\dfrac{56}{65}` && tx(G('cos(T)', r406)) === r`\dfrac{33}{65}` && tx(G('(cosec(T)-cot(T))/(cosec(T)+cot(T))', r406)) === r`\dfrac{16}{49}` && 1089 + 3136 === 4225 && 65 - 33 === 32 && 65 + 33 === 98, 'values'); C.model([r`\dfrac{16}{49}`, 4225, 3136, 32, 98]); });

// =============================================================== Long answer, 10 marks (3 + 3 + 4) (7)
const r011 = fromCot(11, 60);
Q('l01', mk.long({ marks: 10, stem: r`Answer each part.
(a) In triangle $ABC$ right-angled at $B$, derive $\sin^2 A + \cos^2 A = 1$ from Pythagoras' theorem, and then derive $1 + \tan^2 A = \sec^2 A$.
(b) If $\cot A = \dfrac{11}{60}$ and $A$ is acute, find $\sin A$, $\cos A$ and $\sec A$.
(c) Prove that $\dfrac{\sin\theta}{1 - \cos\theta} = \operatorname{cosec}\theta + \cot\theta$.`, model: J([r`(a) Let $AB = p$, $BC = q$ and $AC = h$. Pythagoras gives $p^2 + q^2 = h^2$. Dividing by $h^2$: $\dfrac{p^2}{h^2} + \dfrac{q^2}{h^2} = 1$, and since $\cos A = \dfrac{p}{h}$ and $\sin A = \dfrac{q}{h}$, $\cos^2 A + \sin^2 A = 1$.`, r`Dividing $p^2 + q^2 = h^2$ by $p^2$ instead: $1 + \dfrac{q^2}{p^2} = \dfrac{h^2}{p^2}$, that is $1 + \tan^2 A = \sec^2 A$.`, r`(b) $\operatorname{cosec}^2 A = 1 + \cot^2 A = 1 + \dfrac{121}{3600} = \dfrac{3721}{3600}$, so $\operatorname{cosec} A = \dfrac{61}{60}$ and $\sin A = \dfrac{60}{61}$.`, r`$\cos A = \cot A\sin A = \dfrac{11}{60} \times \dfrac{60}{61} = \dfrac{11}{61}$, so $\sec A = \dfrac{61}{11}$.`, r`(c) Multiply the numerator and denominator by $1 + \cos\theta$: LHS $= \dfrac{\sin\theta(1 + \cos\theta)}{1 - \cos^2\theta} = \dfrac{\sin\theta(1 + \cos\theta)}{\sin^2\theta}$.`, r`$= \dfrac{1 + \cos\theta}{\sin\theta} = \dfrac{1}{\sin\theta} + \dfrac{\cos\theta}{\sin\theta} = \operatorname{cosec}\theta + \cot\theta = $ RHS.`]), sol: 'Part (a): divide the Pythagoras relation by h² and by p². Part (b): 1 + cot² A = cosec² A. Part (c): multiply by the conjugate 1 + cos θ.', scheme: [['(a) Pythagoras divided by h² gives sin² + cos² = 1', 2], ['(a) 1 + tan² A = sec² A', 1], ['(b) cosec A = 61/60 and sin A = 60/61', 1], ['(b) cos A = 11/61', 1], ['(b) sec A = 61/11', 1], ['(c) multiplied by 1 + cos θ', 1], ['(c) denominator sin² θ, cancelled', 1], ['(c) split into cosec θ + cot θ', 2]], d: 3, c: 'application', t: [1, 2], time: 600 }), (C) => {
  C.assert(tx(G('sin(T)', r011)) === r`\dfrac{60}{61}` && tx(G('cos(T)', r011)) === r`\dfrac{11}{61}` && tx(G('sec(T)', r011)) === r`\dfrac{61}{11}` && 121 + 3600 === 3721 && 61 * 61 === 3721, '(b)');
  C.assert(chain('sin(A)/(1-cos(A))', 'sin(A)*(1+cos(A))/(1-cos(A)^2)', 'sin(A)*(1+cos(A))/sin(A)^2', '(1+cos(A))/sin(A)', '1/sin(A)+cos(A)/sin(A)', 'cosec(A)+cot(A)') > 0, '(c) every step equal');
  C.assert(identity('(cos(A)^2)+(sin(A)^2)', '1') > 10 && identity('1+tan(A)^2', 'sec(A)^2') > 10, '(a) identities');
  C.model([r`\dfrac{60}{61}`, r`\dfrac{11}{61}`, r`\dfrac{61}{11}`, 3721]);
});
Q('l02', mk.long({ marks: 10, stem: r`Prove each identity, for acute angles.
(a) Adding a cosine-over-sine-plus-one fraction to its reciprocal pair gives a multiple of secant: $\dfrac{\cos\theta}{1 + \sin\theta} + \dfrac{1 + \sin\theta}{\cos\theta} = 2\sec\theta$.
(b) The gap between $\tan^2\theta$ and $\sin^2\theta$ is their product: $\tan^2\theta - \sin^2\theta = \tan^2\theta\sin^2\theta$.
(c) Powers of secant and tangent match: $\sec^4\theta - \sec^2\theta = \tan^4\theta + \tan^2\theta$.`, model: J([r`(a) LHS $= \dfrac{\cos^2\theta + (1 + \sin\theta)^2}{\cos\theta(1 + \sin\theta)} = \dfrac{\cos^2\theta + 1 + 2\sin\theta + \sin^2\theta}{\cos\theta(1 + \sin\theta)}$.`, r`The numerator is $2 + 2\sin\theta = 2(1 + \sin\theta)$, so LHS $= \dfrac{2}{\cos\theta} = 2\sec\theta$.`, r`(b) LHS $= \tan^2\theta - \sin^2\theta = \dfrac{\sin^2\theta}{\cos^2\theta} - \sin^2\theta = \sin^2\theta\left(\dfrac{1}{\cos^2\theta} - 1\right)$.`, r`$= \sin^2\theta \times \dfrac{1 - \cos^2\theta}{\cos^2\theta} = \sin^2\theta \times \tan^2\theta = $ RHS.`, r`(c) LHS $= \sec^2\theta(\sec^2\theta - 1) = (1 + \tan^2\theta)\tan^2\theta$.`, r`$= \tan^2\theta + \tan^4\theta = $ RHS.`]), sol: 'Part (a): common denominator and sin² + cos² = 1. Part (b): factor out sin² θ. Part (c): factor sec² θ and use sec² θ − 1 = tan² θ.', scheme: [['(a) common denominator', 1], ['(a) numerator 2(1 + sin θ), cancelled to 2 sec θ', 2], ['(b) sin² θ taken out', 1], ['(b) 1 − cos² θ = sin² θ, giving tan² θ sin² θ', 2], ['(c) sec² θ factored', 1], ['(c) 1 + tan² θ used', 1], ['(c) expanded to RHS', 2]], d: 3, c: 'application', t: [2], time: 660 }), (C) => {
  C.assert(chain('cos(A)/(1+sin(A))+(1+sin(A))/cos(A)', '(cos(A)^2+(1+sin(A))^2)/(cos(A)*(1+sin(A)))', '(cos(A)^2+1+2*sin(A)+sin(A)^2)/(cos(A)*(1+sin(A)))', '2*(1+sin(A))/(cos(A)*(1+sin(A)))', '2*sec(A)') > 0, '(a)');
  C.assert(chain('tan(A)^2-sin(A)^2', 'sin(A)^2/cos(A)^2-sin(A)^2', 'sin(A)^2*(1/cos(A)^2-1)', 'sin(A)^2*(1-cos(A)^2)/cos(A)^2', 'sin(A)^2*tan(A)^2') > 0, '(b)');
  C.assert(chain('sec(A)^4-sec(A)^2', 'sec(A)^2*(sec(A)^2-1)', '(1+tan(A)^2)*tan(A)^2', 'tan(A)^2+tan(A)^4', 'tan(A)^4+tan(A)^2') > 0, '(c)');
  C.model([r`2 + 2\sin\theta`, r`\sin^2\theta`, r`\tan^4\theta`]);
});
const r03c = fromTan(40, 9);
Q('l03', mk.long({ marks: 10, stem: r`Answer each part.
(a) An acute angle $\theta$ has $\tan\theta = \dfrac{40}{9}$. Find $\sin\theta$ and $\cos\theta$.
(b) Hence evaluate $\dfrac{\sec\theta + \tan\theta}{\sec\theta - \tan\theta}$.
(c) Verify with your values that $\sec^2\theta - \tan^2\theta = 1$ and $\operatorname{cosec}^2\theta - \cot^2\theta = 1$.`, model: J([r`(a) $\sec^2\theta = 1 + \tan^2\theta = 1 + \dfrac{1600}{81} = \dfrac{1681}{81}$, so $\sec\theta = \dfrac{41}{9}$ and $\cos\theta = \dfrac{9}{41}$.`, r`$\sin\theta = \tan\theta\cos\theta = \dfrac{40}{9} \times \dfrac{9}{41} = \dfrac{40}{41}$.`, r`(b) $\dfrac{\sec\theta + \tan\theta}{\sec\theta - \tan\theta} = \dfrac{\frac{41}{9} + \frac{40}{9}}{\frac{41}{9} - \frac{40}{9}} = \dfrac{81/9}{1/9} = 81$.`, r`(c) $\sec^2\theta - \tan^2\theta = \dfrac{1681}{81} - \dfrac{1600}{81} = \dfrac{81}{81} = 1$.`, r`$\operatorname{cosec}\theta = \dfrac{41}{40}$ and $\cot\theta = \dfrac{9}{40}$, so $\operatorname{cosec}^2\theta - \cot^2\theta = \dfrac{1681}{1600} - \dfrac{81}{1600} = \dfrac{1600}{1600} = 1$.`]), sol: 'Find sec from 1 + tan² θ, then cos and sin; every part then uses the exact fractions.', scheme: [['(a) sec θ = 41/9', 1], ['(a) cos θ = 9/41 and sin θ = 40/41', 2], ['(b) substitution', 1], ['(b) value 81', 2], ['(c) sec² − tan² = 1', 2], ['(c) cosec² − cot² = 1', 2]], d: 3, c: 'application', t: [1, 3], time: 600 }), (C) => {
  C.assert(tx(G('sin(T)', r03c)) === r`\dfrac{40}{41}` && tx(G('cos(T)', r03c)) === r`\dfrac{9}{41}` && tx(G('(sec(T)+tan(T))/(sec(T)-tan(T))', r03c)) === '81' && 1600 + 81 === 1681 && 1681 - 1600 === 81, '(a) and (b)');
  C.assert(tx(G('sec(T)^2-tan(T)^2', r03c)) === '1' && tx(G('cosec(T)^2-cot(T)^2', r03c)) === '1' && 41 * 41 === 1681 && 40 * 40 === 1600, '(c)');
  C.model([r`\dfrac{40}{41}`, r`\dfrac{9}{41}`, 81, 1681, 1600]);
});
Q('l04', mk.long({ marks: 10, stem: r`Answer each part.
(a) Without tables, evaluate $\dfrac{\sin^2 28^\circ + \sin^2 62^\circ}{\tan 14^\circ\tan 76^\circ} + \cot^2 30^\circ$.
(b) If $\sec 4\theta = \operatorname{cosec}(\theta - 20^\circ)$, where $4\theta$ is acute, find $\theta$.
(c) Prove that $(\sec\theta - \cos\theta)(\operatorname{cosec}\theta - \sin\theta) = \dfrac{1}{\tan\theta + \cot\theta}$.`, model: J([r`(a) $\sin 62^\circ = \cos 28^\circ$, so the numerator is $\sin^2 28^\circ + \cos^2 28^\circ = 1$. Also $\tan 76^\circ = \cot 14^\circ$, so the denominator is $\tan 14^\circ\cot 14^\circ = 1$.`, r`With $\cot^2 30^\circ = 3$, the value is $\dfrac{1}{1} + 3 = 4$.`, r`(b) $\sec 4\theta = \operatorname{cosec}(90^\circ - 4\theta)$, so $90^\circ - 4\theta = \theta - 20^\circ$, giving $5\theta = 110^\circ$ and $\theta = 22^\circ$. Check: $4\theta = 88^\circ$ is acute and $\theta - 20^\circ = 2^\circ$.`, r`(c) LHS $= \left(\dfrac{1}{\cos\theta} - \cos\theta\right)\left(\dfrac{1}{\sin\theta} - \sin\theta\right) = \dfrac{1 - \cos^2\theta}{\cos\theta} \times \dfrac{1 - \sin^2\theta}{\sin\theta}$.`, r`$= \dfrac{\sin^2\theta}{\cos\theta} \times \dfrac{\cos^2\theta}{\sin\theta} = \sin\theta\cos\theta$.`, r`RHS $= \dfrac{1}{\frac{\sin\theta}{\cos\theta} + \frac{\cos\theta}{\sin\theta}} = \dfrac{1}{\frac{\sin^2\theta + \cos^2\theta}{\sin\theta\cos\theta}} = \sin\theta\cos\theta$.`, r`So LHS $=$ RHS.`]), sol: 'Part (a): complementary angles turn the numerator into sin² + cos² and the denominator into tan × cot. Part (b): sec x = cosec(90° − x). Part (c): simplify each side to sin θ cos θ.', scheme: [['(a) numerator = 1', 1], ['(a) denominator = 1', 1], ['(a) value 4', 1], ['(b) complementary form', 1], ['(b) θ = 22°', 2], ['(c) LHS = sin θ cos θ', 2], ['(c) RHS = sin θ cos θ', 2]], d: 4, c: 'analysis', t: [2, 3], time: 720 }), (C) => {
  C.assert(close(Fl('(sin(28)^2+sin(62)^2)/(tan(14)*tan(76))+cot(30)^2'), 4) && val('cot(30)^2') === 3, '(a) = 4');
  const f = (A) => Fl('sec(4*A)-cosec(A-20)', { A });
  C.assert(close(f(22), 0) && ![18, 24, 26, 30].some((A) => close(f(A), 0)) && 5 * 22 === 110 && 4 * 22 === 88, '(b) theta = 22');
  C.assert(chain('(sec(A)-cos(A))*(cosec(A)-sin(A))', '(1-cos(A)^2)/cos(A)*(1-sin(A)^2)/sin(A)', 'sin(A)^2/cos(A)*cos(A)^2/sin(A)', 'sin(A)*cos(A)', '1/(tan(A)+cot(A))') > 0, '(c) every step equal');
  C.model([1, 3, 4, 22, 110, r`\sin\theta\cos\theta`]);
});
Q('l05', mk.long({ marks: 10, stem: r`Eliminate $\theta$ in each case, for acute $\theta$.
(a) If $x = 4\cos\theta$ and $y = 3\sin\theta$, show that $\dfrac{x^2}{16} + \dfrac{y^2}{9} = 1$.
(b) If $x = 2\sec\theta$ and $y = 3\tan\theta$, show that $\dfrac{x^2}{4} - \dfrac{y^2}{9} = 1$.
(c) If $x = 3 + 5\cos\theta$ and $y = 2 + 5\sin\theta$, show that $(x - 3)^2 + (y - 2)^2 = 25$, and find $\sin\theta$ and $\cos\theta$ when $x = 7$, $y = 5$.`, model: J([r`(a) $\dfrac{x^2}{16} + \dfrac{y^2}{9} = \dfrac{16\cos^2\theta}{16} + \dfrac{9\sin^2\theta}{9} = \cos^2\theta + \sin^2\theta = 1$.`, r`(b) $\dfrac{x^2}{4} - \dfrac{y^2}{9} = \dfrac{4\sec^2\theta}{4} - \dfrac{9\tan^2\theta}{9} = \sec^2\theta - \tan^2\theta = 1$.`, r`(c) $x - 3 = 5\cos\theta$ and $y - 2 = 5\sin\theta$, so $(x - 3)^2 + (y - 2)^2 = 25\cos^2\theta + 25\sin^2\theta = 25(\cos^2\theta + \sin^2\theta) = 25$.`, r`For $x = 7$ and $y = 5$: $5\cos\theta = 4$ and $5\sin\theta = 3$, so $\cos\theta = \dfrac{4}{5}$ and $\sin\theta = \dfrac{3}{5}$. Check: $16 + 9 = 25$.`]), sol: 'Write x and y with the given ratios, square, and use the Pythagorean identities so that θ disappears.', scheme: [['(a) squared and simplified', 1], ['(a) sin² + cos² = 1', 2], ['(b) squared with sec² and tan²', 1], ['(b) sec² − tan² = 1', 2], ['(c) x − 3 and y − 2 squared and added', 2], ['(c) cos θ = 4/5 and sin θ = 3/5', 2]], d: 3, c: 'application', t: [3], time: 660 }), (C) => {
  C.assert(identity('(4*cos(A))^2/16+(3*sin(A))^2/9', '1') > 10 && identity('(2*sec(A))^2/4-(3*tan(A))^2/9', '1') > 10 && identity('(5*cos(A))^2+(5*sin(A))^2', '25') > 10, '(a), (b), (c) hold at every angle');
  C.assert(fails('(4*cos(A))^2/9+(3*sin(A))^2/16', '1'), 'swapping the denominators breaks (a)');
  const g = fromSin(3, 5);
  C.assert(tx(G('5*cos(T)', g)) === '4' && tx(G('5*sin(T)', g)) === '3' && 7 - 3 === 4 && 5 - 2 === 3 && 16 + 9 === 25, '(c) point (7, 5)');
  C.model([25, r`\dfrac{4}{5}`, r`\dfrac{3}{5}`]);
});
const r06b = fromCosec(37, 12);
Q('l06', mk.long({ marks: 10, stem: r`Answer each part.
(a) Given $\operatorname{cosec}\theta = \dfrac{37}{12}$ with $\theta$ acute, find $\cos\theta$ and $\cot\theta$.
(b) Hence find the value of $\dfrac{\cos\theta + \sin\theta}{\cos\theta - \sin\theta}$.
(c) Prove that $\dfrac{1}{\sec\theta - \tan\theta} - \dfrac{1}{\cos\theta} = \tan\theta$.`, model: J([r`(a) $\cot^2\theta = \operatorname{cosec}^2\theta - 1 = \dfrac{1369}{144} - 1 = \dfrac{1225}{144}$, so $\cot\theta = \dfrac{35}{12}$.`, r`$\sin\theta = \dfrac{12}{37}$ and $\cos\theta = \cot\theta\sin\theta = \dfrac{35}{12} \times \dfrac{12}{37} = \dfrac{35}{37}$.`, r`(b) $\dfrac{\cos\theta + \sin\theta}{\cos\theta - \sin\theta} = \dfrac{35 + 12}{35 - 12} = \dfrac{47}{23}$.`, r`(c) $\dfrac{1}{\sec\theta - \tan\theta} = \dfrac{1}{\frac{1 - \sin\theta}{\cos\theta}} = \dfrac{\cos\theta}{1 - \sin\theta}$.`, r`Multiplying by $1 + \sin\theta$: $\dfrac{\cos\theta(1 + \sin\theta)}{1 - \sin^2\theta} = \dfrac{\cos\theta(1 + \sin\theta)}{\cos^2\theta} = \dfrac{1 + \sin\theta}{\cos\theta}$.`, r`So LHS $= \dfrac{1 + \sin\theta}{\cos\theta} - \dfrac{1}{\cos\theta} = \dfrac{\sin\theta}{\cos\theta} = \tan\theta = $ RHS.`]), sol: 'Part (a): 1 + cot² θ = cosec² θ. Part (c): turn sec θ − tan θ into one fraction and rationalise with 1 + sin θ.', scheme: [['(a) cot θ = 35/12', 1], ['(a) sin θ = 12/37 and cos θ = 35/37', 2], ['(b) substitution', 1], ['(b) 47/23', 2], ['(c) 1/(sec − tan) = cos/(1 − sin)', 1], ['(c) multiplied by 1 + sin θ', 1], ['(c) subtraction gives tan θ', 2]], d: 3, c: 'application', t: [2, 3], time: 660 }), (C) => {
  C.assert(tx(G('cos(T)', r06b)) === r`\dfrac{35}{37}` && tx(G('cot(T)', r06b)) === r`\dfrac{35}{12}` && tx(G('(cos(T)+sin(T))/(cos(T)-sin(T))', r06b)) === r`\dfrac{47}{23}` && 1369 - 144 === 1225 && 35 * 35 === 1225 && 35 + 12 === 47 && 35 - 12 === 23, '(a) and (b)');
  C.assert(chain('1/(sec(A)-tan(A))-1/cos(A)', 'cos(A)/(1-sin(A))-1/cos(A)', 'cos(A)*(1+sin(A))/(1-sin(A)^2)-1/cos(A)', '(1+sin(A))/cos(A)-1/cos(A)', 'sin(A)/cos(A)', 'tan(A)') > 0, '(c) every step equal');
  C.model([r`\dfrac{35}{37}`, r`\dfrac{35}{12}`, r`\dfrac{47}{23}`, 1369, 1225]);
});
Q('l07', mk.long({ marks: 10, stem: r`Answer each part.
(a) Using values of standard angles and complementary angles, evaluate $\tan^2 30^\circ + \operatorname{cosec}^2 45^\circ\sec^2 60^\circ - \cot 15^\circ\cot 75^\circ$.
(b) If $\sin(2A + 14^\circ) = \cos(3A - 4^\circ)$, find $A$ and the common value of the two sides, written as a sine and as a cosine.
(c) Prove that $\dfrac{\sin(90^\circ - \theta)\operatorname{cosec}\theta}{\tan(90^\circ - \theta)} + \sin^2\theta + \sin^2(90^\circ - \theta) = 2$.`, model: J([r`(a) $\tan^2 30^\circ = \dfrac{1}{3}$, $\operatorname{cosec}^2 45^\circ = 2$, $\sec^2 60^\circ = 4$, and $\cot 75^\circ = \tan 15^\circ$ so $\cot 15^\circ\cot 75^\circ = 1$.`, r`Value $= \dfrac{1}{3} + 2 \times 4 - 1 = \dfrac{22}{3}$.`, r`(b) $\sin(2A + 14^\circ) = \cos(90^\circ - 2A - 14^\circ)$, so $3A - 4^\circ = 76^\circ - 2A$, giving $5A = 80^\circ$ and $A = 16^\circ$.`, r`Then $2A + 14^\circ = 46^\circ$ and $3A - 4^\circ = 44^\circ$, so both sides equal $\sin 46^\circ = \cos 44^\circ$.`, r`(c) $\sin(90^\circ - \theta) = \cos\theta$ and $\tan(90^\circ - \theta) = \cot\theta$, so the first term is $\dfrac{\cos\theta\operatorname{cosec}\theta}{\cot\theta}$.`, r`$= \dfrac{\cos\theta}{\sin\theta} \div \dfrac{\cos\theta}{\sin\theta} = 1$.`, r`Also $\sin^2(90^\circ - \theta) = \cos^2\theta$, so LHS $= 1 + \sin^2\theta + \cos^2\theta = 1 + 1 = 2$.`]), sol: 'Part (a): standard values and cot 75° = tan 15°. Part (b): cos x = sin(90° − x), so the angles add to 90°. Part (c): replace each complementary ratio, then sin² + cos² = 1.', scheme: [['(a) standard values 1/3, 2 and 4', 1], ['(a) cot 15° cot 75° = 1', 1], ['(a) 22/3', 1], ['(b) 5A = 80°', 1], ['(b) A = 16° and sin 46° = cos 44°', 2], ['(c) complementary ratios replaced', 1], ['(c) first term = 1', 1], ['(c) sin² + cos² = 1, total 2', 2]], d: 4, c: 'analysis', t: [2, 3], time: 720 }), (C) => {
  C.assert(tx(E('tan(30)^2+cosec(45)^2*sec(60)^2-1')) === r`\dfrac{22}{3}` && close(Fl('tan(30)^2+cosec(45)^2*sec(60)^2-cot(15)*cot(75)'), 22 / 3), '(a) = 22/3');
  const f = (A) => Fl('sin(2*A+14)-cos(3*A-4)', { A });
  C.assert(close(f(16), 0) && !close(f(20), 0) && !close(f(10), 0) && 90 - 14 === 76 && 2 * 16 + 14 === 46 && 3 * 16 - 4 === 44 && close(Fl('sin(46)'), Fl('cos(44)')), '(b) A = 16');
  C.assert(chain('sin(90-A)*cosec(A)/tan(90-A)+sin(A)^2+sin(90-A)^2', 'cos(A)*cosec(A)/cot(A)+sin(A)^2+cos(A)^2', '1+sin(A)^2+cos(A)^2', '2') > 0, '(c) every step equal');
  C.model([r`\dfrac{22}{3}`, 16, 46, 44, 2]);
});
